-- Unpublished MCP registry/OAuth domain. Drain every old writer before independent DDL.
-- The single combined fingerprint was derived from isolated real MySQL metadata.
-- An uncalibrated placeholder is rejected BEFORE any DDL, including fresh predecessors.
-- No OAuth network operation, credential backfill, grant or lifecycle completion occurs here.
SET @mcp_previous_gcml=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=1048576;
SET @mcp_predecessor_ok=(SELECT COUNT(*)=1 FROM schema_migrations WHERE BINARY name=BINARY '0061_skill_registry_native_lookup.sql');
SET @mcp_old_triggers_ok=(SELECT COUNT(*)=763 AND COUNT(DISTINCT trigger_name)=763 AND SUM(OCTET_LENGTH(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4','')))))+COUNT(*)-1<=@@SESSION.group_concat_max_len AND SHA2(GROUP_CONCAT(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY event_object_table,trigger_name SEPARATOR '|'),256)='f768e4e5f695689cfc04272abf4746d364a8d355a7e46cedcaef5dda19e7ac50' FROM information_schema.triggers WHERE trigger_schema=DATABASE());
SET @migration_sql=IF(@mcp_predecessor_ok=1 AND @mcp_old_triggers_ok=1,'SELECT 1','SELECT 1 FROM __invalid_mcp_registry_predecessor__');
PREPARE migration_stmt FROM @migration_sql;
EXECUTE migration_stmt;
DEALLOCATE PREPARE migration_stmt;

CREATE TABLE mcp_registry_controls (
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  owner_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  owner_json JSON NOT NULL,
  owner_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  owner_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  name VARCHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_json JSON NULL,
  PRIMARY KEY (registration_id), UNIQUE KEY uk_mcp_owner_name (owner_sha256,name),
  KEY idx_mcp_owner_tenant (owner_tenant_id,registration_id),
  CONSTRAINT chk_mcp_owner CHECK ((JSON_UNQUOTE(JSON_EXTRACT(owner_json,'$.scope'))='platform' AND owner_tenant_id IS NULL AND owner_user_id IS NULL) OR (JSON_UNQUOTE(JSON_EXTRACT(owner_json,'$.scope'))='tenant' AND owner_tenant_id IS NOT NULL AND owner_user_id IS NULL) OR (JSON_UNQUOTE(JSON_EXTRACT(owner_json,'$.scope'))='user' AND owner_tenant_id IS NOT NULL AND owner_user_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_versions (
  config_version_id CHAR(36) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  record_json JSON NOT NULL,
  config_generation BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(record_json,'$.generation')) STORED,
  KEY idx_mcp_versions_subject (registration_id,subject_tenant_id,subject_user_id,config_generation,config_version_id),
  PRIMARY KEY (config_version_id), KEY idx_mcp_version_registration (registration_id,config_version_id),
  CONSTRAINT fk_mcp_version_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_authorizations (
  authorization_key CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_json JSON NOT NULL,
  authorization_epoch BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(record_json,'$.authorizationEpoch')) STORED,
  KEY idx_mcp_authorizations_subject (registration_id,subject_tenant_id,subject_user_id,authorization_epoch,authorization_key),
  PRIMARY KEY (authorization_key), UNIQUE KEY uk_mcp_authorization_subject (registration_id,subject_tenant_id,subject_user_id),
  KEY idx_mcp_authorization_tenant (subject_tenant_id,authorization_key),
  CONSTRAINT fk_mcp_authorization_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_pending (
  authorization_id CHAR(36) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_json JSON NOT NULL,
  state_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  authorization_epoch BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(record_json,'$.authorizationEpoch')) STORED,
  KEY idx_mcp_pending_subject (registration_id,subject_tenant_id,subject_user_id,authorization_epoch,authorization_id),
  PRIMARY KEY (authorization_id), UNIQUE KEY uk_mcp_pending_state (state_sha256), KEY idx_mcp_pending_registration (registration_id,authorization_id),
  CONSTRAINT fk_mcp_pending_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_operations (
  operation_id CHAR(36) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_json JSON NOT NULL,
  authorization_key CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  authorization_epoch BIGINT UNSIGNED NOT NULL,
  predecessor_token_revision BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (operation_id), KEY idx_mcp_operation_registration (registration_id,operation_id),
  UNIQUE KEY uk_mcp_operation_predecessor (authorization_key,authorization_epoch,predecessor_token_revision),
  KEY idx_mcp_operations_subject (registration_id,subject_tenant_id,subject_user_id,authorization_epoch,operation_id),
  CONSTRAINT fk_mcp_operation_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_credentials (
  credential_version_id CHAR(36) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NOT NULL,
  record_json JSON NOT NULL,
  authorization_epoch BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(record_json,'$.authorizationEpoch')) STORED,
  KEY idx_mcp_credentials_subject (registration_id,subject_tenant_id,subject_user_id,authorization_epoch,credential_version_id),
  PRIMARY KEY (credential_version_id), KEY idx_mcp_credential_registration (registration_id,credential_version_id),
  CONSTRAINT fk_mcp_credential_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_materials (
  material_id CHAR(36) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  record_json JSON NOT NULL,
  authorization_epoch BIGINT UNSIGNED GENERATED ALWAYS AS (JSON_EXTRACT(record_json,'$.aad.authorizationEpoch')) STORED,
  KEY idx_mcp_materials_subject (registration_id,subject_tenant_id,subject_user_id,authorization_epoch,material_id),
  PRIMARY KEY (material_id), KEY idx_mcp_material_registration (registration_id,material_id),
  CONSTRAINT fk_mcp_material_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TABLE mcp_registry_replays (
  key_sha256 CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  registration_id CHAR(64) COLLATE utf8mb4_0900_as_cs NOT NULL,
  subject_tenant_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  subject_user_id VARCHAR(128) COLLATE utf8mb4_0900_as_cs NULL,
  record_json JSON NOT NULL,
  authorization_epoch BIGINT UNSIGNED GENERATED ALWAYS AS (COALESCE(JSON_EXTRACT(record_json,'$.result.authorizationEpoch'),0)) STORED,
  KEY idx_mcp_replays_subject (registration_id,subject_tenant_id,subject_user_id,authorization_epoch,key_sha256),
  PRIMARY KEY (key_sha256), KEY idx_mcp_replay_registration (registration_id,key_sha256),
  CONSTRAINT fk_mcp_replay_registration FOREIGN KEY (registration_id) REFERENCES mcp_registry_controls(registration_id) ON UPDATE RESTRICT ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs;

CREATE TRIGGER trg_mcp_registry_controls_bi BEFORE INSERT ON mcp_registry_controls FOR EACH ROW BEGIN IF (JSON_TYPE(NEW.owner_json)='OBJECT' AND JSON_LENGTH(NEW.owner_json)=3 AND ((NEW.owner_tenant_id IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.owner_json,'$.tenantId'))='NULL') OR BINARY NEW.owner_tenant_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.owner_json,'$.tenantId'))) AND ((NEW.owner_user_id IS NULL AND JSON_TYPE(JSON_EXTRACT(NEW.owner_json,'$.userId'))='NULL') OR BINARY NEW.owner_user_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.owner_json,'$.userId'))) AND NEW.record_json IS NULL AND (NEW.owner_tenant_id IS NULL OR (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.owner_tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.owner_tenant_id AND BINARY t.tenant_id=BINARY NEW.owner_tenant_id AND BINARY t.subject_id=BINARY NEW.owner_tenant_id AND t.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.owner_tenant_id AND BINARY a.tenant_id=BINARY NEW.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.owner_tenant_id AND BINARY f.tenant_id=BINARY NEW.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.owner_tenant_id AND BINARY r.tenant_id=BINARY NEW.owner_tenant_id FOR SHARE) AND (NEW.owner_user_id IS NULL OR EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.owner_tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.owner_user_id AND BINARY u.tenant_id=BINARY NEW.owner_tenant_id AND BINARY u.subject_id=BINARY NEW.owner_user_id AND u.state='active' FOR SHARE))))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP owner is not active'; END IF; END;
CREATE TRIGGER trg_mcp_registry_controls_bu BEFORE UPDATE ON mcp_registry_controls FOR EACH ROW BEGIN IF (BINARY NEW.registration_id=BINARY OLD.registration_id AND BINARY NEW.owner_sha256=BINARY OLD.owner_sha256 AND NEW.owner_json=OLD.owner_json AND (NEW.owner_tenant_id<=>OLD.owner_tenant_id) AND (NEW.owner_user_id<=>OLD.owner_user_id) AND BINARY NEW.name=BINARY OLD.name AND ((NEW.record_json<=>OLD.record_json) OR (JSON_TYPE(NEW.record_json)='OBJECT' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND JSON_EXTRACT(NEW.record_json,'$.owner')=NEW.owner_json AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.name'))=BINARY NEW.name AND ((OLD.record_json IS NULL AND JSON_EXTRACT(NEW.record_json,'$.revision')=1 AND JSON_EXTRACT(NEW.record_json,'$.generation')=1) OR (OLD.record_json IS NOT NULL AND JSON_EXTRACT(NEW.record_json,'$.revision')=JSON_EXTRACT(OLD.record_json,'$.revision')+1 AND JSON_EXTRACT(NEW.record_json,'$.generation')>=JSON_EXTRACT(OLD.record_json,'$.generation') AND JSON_EXTRACT(NEW.record_json,'$.generation')<=JSON_EXTRACT(OLD.record_json,'$.generation')+1 AND JSON_EXTRACT(NEW.record_json,'$.updatedAtMs')>=JSON_EXTRACT(OLD.record_json,'$.updatedAtMs')))))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP registration transition is invalid'; END IF; END;
CREATE TRIGGER trg_mcp_registry_controls_bd BEFORE DELETE ON mcp_registry_controls FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP registration identity is permanent';

CREATE TRIGGER trg_mcp_registry_versions_bi BEFORE INSERT ON mcp_registry_versions FOR EACH ROW BEGIN IF (NEW.subject_tenant_id IS NULL AND NEW.subject_user_id IS NULL AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId'))=BINARY NEW.config_version_id AND EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND JSON_EXTRACT(NEW.record_json,'$.owner')=c.owner_json AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY c.registration_id)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP version requires exact registration'; END IF; END;
CREATE TRIGGER trg_mcp_registry_versions_bu BEFORE UPDATE ON mcp_registry_versions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP config version is immutable';
CREATE TRIGGER trg_mcp_registry_versions_bd BEFORE DELETE ON mcp_registry_versions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP config version is immutable';

CREATE TRIGGER trg_mcp_registry_authorizations_bi BEFORE INSERT ON mcp_registry_authorizations FOR EACH ROW BEGIN IF (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.authorizationKey'))=BINARY NEW.authorization_key AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.tenantId'))=BINARY NEW.subject_tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.userId'))=BINARY NEW.subject_user_id AND JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch')=1 AND JSON_EXTRACT(NEW.record_json,'$.tokenRevision')=0 AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))='pending' AND EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.state'))='enabled' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.currentVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND JSON_EXTRACT(c.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND JSON_EXTRACT(c.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND (c.owner_tenant_id IS NULL OR BINARY c.owner_tenant_id=BINARY NEW.subject_tenant_id) AND (c.owner_user_id IS NULL OR BINARY c.owner_user_id=BINARY NEW.subject_user_id)) AND EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.subject_tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.subject_tenant_id AND BINARY t.tenant_id=BINARY NEW.subject_tenant_id AND BINARY t.subject_id=BINARY NEW.subject_tenant_id AND t.state='active' FOR SHARE) AND EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.subject_tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.subject_tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.subject_tenant_id AND BINARY a.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.subject_tenant_id AND BINARY f.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.subject_tenant_id AND BINARY r.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP credential subject is not active'; END IF; END;
CREATE TRIGGER trg_mcp_registry_authorizations_bu BEFORE UPDATE ON mcp_registry_authorizations FOR EACH ROW BEGIN IF (BINARY NEW.authorization_key=BINARY OLD.authorization_key AND BINARY NEW.registration_id=BINARY OLD.registration_id AND BINARY NEW.subject_tenant_id=BINARY OLD.subject_tenant_id AND BINARY NEW.subject_user_id=BINARY OLD.subject_user_id AND JSON_EXTRACT(NEW.record_json,'$.subject')=JSON_EXTRACT(OLD.record_json,'$.subject') AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.authorizationKey'))=BINARY NEW.authorization_key AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch')>=JSON_EXTRACT(OLD.record_json,'$.authorizationEpoch') AND JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch')<=JSON_EXTRACT(OLD.record_json,'$.authorizationEpoch')+1 AND JSON_EXTRACT(NEW.record_json,'$.tokenRevision')>=JSON_EXTRACT(OLD.record_json,'$.tokenRevision') AND JSON_EXTRACT(NEW.record_json,'$.tokenRevision')<=JSON_EXTRACT(OLD.record_json,'$.tokenRevision')+1 AND (JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch')>JSON_EXTRACT(OLD.record_json,'$.authorizationEpoch') OR (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(OLD.record_json,'$.configVersionId')) AND JSON_EXTRACT(NEW.record_json,'$.registrationGeneration')=JSON_EXTRACT(OLD.record_json,'$.registrationGeneration') AND JSON_EXTRACT(NEW.record_json,'$.registrationRevision')=JSON_EXTRACT(OLD.record_json,'$.registrationRevision'))) AND (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state')) NOT IN ('pending','connected') OR EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.state'))='enabled' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.currentVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND JSON_EXTRACT(c.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(c.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration'))) AND JSON_EXTRACT(NEW.record_json,'$.updatedAtMs')>=JSON_EXTRACT(OLD.record_json,'$.updatedAtMs')) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP authorization CAS is invalid'; END IF; END;
CREATE TRIGGER trg_mcp_registry_authorizations_bd BEFORE DELETE ON mcp_registry_authorizations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP authorization identity is permanent';

CREATE TRIGGER trg_mcp_registry_pending_bi BEFORE INSERT ON mcp_registry_pending FOR EACH ROW BEGIN IF (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.authorizationId'))=BINARY NEW.authorization_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.stateSha256'))=BINARY NEW.state_sha256 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.tenantId'))=BINARY NEW.subject_tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.userId'))=BINARY NEW.subject_user_id AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))='pending' AND JSON_EXTRACT(NEW.record_json,'$.consumedAtMs')=CAST('null' AS JSON) AND JSON_EXTRACT(NEW.record_json,'$.expiresAtMs')>JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND EXISTS (SELECT 1 FROM mcp_registry_authorizations a WHERE a.authorization_key=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.authorizationKey')) AND BINARY a.authorization_key=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.authorizationKey')) AND BINARY a.registration_id=BINARY NEW.registration_id AND BINARY a.subject_tenant_id=BINARY NEW.subject_tenant_id AND BINARY a.subject_user_id=BINARY NEW.subject_user_id AND a.registration_id=NEW.registration_id AND a.subject_tenant_id=NEW.subject_tenant_id AND a.subject_user_id=NEW.subject_user_id AND JSON_UNQUOTE(JSON_EXTRACT(a.record_json,'$.state'))='pending' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(a.record_json,'$.configVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND JSON_EXTRACT(a.record_json,'$.registrationRevision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(a.record_json,'$.registrationGeneration')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND JSON_EXTRACT(a.record_json,'$.authorizationEpoch')=JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch'))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP pending state requires exact subject'; END IF; END;
CREATE TRIGGER trg_mcp_registry_pending_bu BEFORE UPDATE ON mcp_registry_pending FOR EACH ROW BEGIN IF (BINARY NEW.authorization_id=BINARY OLD.authorization_id AND BINARY NEW.registration_id=BINARY OLD.registration_id AND BINARY NEW.state_sha256=BINARY OLD.state_sha256 AND BINARY NEW.subject_tenant_id=BINARY OLD.subject_tenant_id AND BINARY NEW.subject_user_id=BINARY OLD.subject_user_id AND JSON_REMOVE(NEW.record_json,'$.state','$.consumedAtMs')=JSON_REMOVE(OLD.record_json,'$.state','$.consumedAtMs') AND JSON_UNQUOTE(JSON_EXTRACT(OLD.record_json,'$.state'))='pending' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state')) IN ('consumed','invalidated')) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP state is single use'; END IF; END;
CREATE TRIGGER trg_mcp_registry_pending_bd BEFORE DELETE ON mcp_registry_pending FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP state identity is permanent';

CREATE TRIGGER trg_mcp_registry_operations_bi BEFORE INSERT ON mcp_registry_operations FOR EACH ROW BEGIN IF (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.operationId'))=BINARY NEW.operation_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.authorizationKey'))=BINARY NEW.authorization_key AND JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch')=NEW.authorization_epoch AND JSON_EXTRACT(NEW.record_json,'$.predecessorTokenRevision')=NEW.predecessor_token_revision AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.tenantId'))=BINARY NEW.subject_tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.userId'))=BINARY NEW.subject_user_id AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))='pending' AND JSON_EXTRACT(NEW.record_json,'$.deadlineAtMs')>JSON_EXTRACT(NEW.record_json,'$.createdAtMs') AND EXISTS (SELECT 1 FROM mcp_registry_authorizations a WHERE a.authorization_key=NEW.authorization_key AND BINARY a.authorization_key=BINARY NEW.authorization_key AND BINARY a.registration_id=BINARY NEW.registration_id AND BINARY a.subject_tenant_id=BINARY NEW.subject_tenant_id AND BINARY a.subject_user_id=BINARY NEW.subject_user_id AND a.registration_id=NEW.registration_id AND a.subject_tenant_id=NEW.subject_tenant_id AND a.subject_user_id=NEW.subject_user_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(a.record_json,'$.configVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND JSON_EXTRACT(a.record_json,'$.registrationRevision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(a.record_json,'$.registrationGeneration')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND JSON_EXTRACT(a.record_json,'$.authorizationEpoch')=NEW.authorization_epoch AND JSON_EXTRACT(a.record_json,'$.tokenRevision')=NEW.predecessor_token_revision)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP operation requires exact predecessor'; END IF; END;
CREATE TRIGGER trg_mcp_registry_operations_bu BEFORE UPDATE ON mcp_registry_operations FOR EACH ROW BEGIN IF (BINARY NEW.operation_id=BINARY OLD.operation_id AND BINARY NEW.registration_id=BINARY OLD.registration_id AND BINARY NEW.subject_tenant_id=BINARY OLD.subject_tenant_id AND BINARY NEW.subject_user_id=BINARY OLD.subject_user_id AND BINARY NEW.authorization_key=BINARY OLD.authorization_key AND NEW.authorization_epoch=OLD.authorization_epoch AND NEW.predecessor_token_revision=OLD.predecessor_token_revision AND JSON_REMOVE(NEW.record_json,'$.state','$.resultSha256','$.completedAtMs')=JSON_REMOVE(OLD.record_json,'$.state','$.resultSha256','$.completedAtMs') AND JSON_UNQUOTE(JSON_EXTRACT(OLD.record_json,'$.state'))='pending' AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state')) IN ('succeeded','failed_not_dispatched','outcome_unknown')) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP operation cannot be reclaimed'; END IF; END;
CREATE TRIGGER trg_mcp_registry_operations_bd BEFORE DELETE ON mcp_registry_operations FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP operation identity is permanent';

CREATE TRIGGER trg_mcp_registry_credentials_bi BEFORE INSERT ON mcp_registry_credentials FOR EACH ROW BEGIN IF (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.credentialVersionId'))=BINARY NEW.credential_version_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.registrationId'))=BINARY NEW.registration_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.tenantId'))=BINARY NEW.subject_tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.subject.userId'))=BINARY NEW.subject_user_id AND EXISTS (SELECT 1 FROM mcp_registry_operations o WHERE o.operation_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.operationId')) AND BINARY o.operation_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.operationId')) AND BINARY o.registration_id=BINARY NEW.registration_id AND BINARY o.subject_tenant_id=BINARY NEW.subject_tenant_id AND BINARY o.subject_user_id=BINARY NEW.subject_user_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(o.record_json,'$.resultCredentialVersionId'))=BINARY NEW.credential_version_id AND o.registration_id=NEW.registration_id AND o.subject_tenant_id=NEW.subject_tenant_id AND o.subject_user_id=NEW.subject_user_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(o.record_json,'$.configVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')) AND JSON_EXTRACT(o.record_json,'$.registrationRevision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(o.record_json,'$.registrationGeneration')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND JSON_UNQUOTE(JSON_EXTRACT(o.record_json,'$.state'))='pending' AND JSON_EXTRACT(NEW.record_json,'$.authorizationEpoch')=o.authorization_epoch AND JSON_EXTRACT(NEW.record_json,'$.tokenRevision')=o.predecessor_token_revision+1) AND EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.state'))='enabled' AND JSON_EXTRACT(c.record_json,'$.revision')=JSON_EXTRACT(NEW.record_json,'$.registrationRevision') AND JSON_EXTRACT(c.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.registrationGeneration') AND BINARY JSON_UNQUOTE(JSON_EXTRACT(c.record_json,'$.currentVersionId'))=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.configVersionId')))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP token requires exact operation'; END IF; END;
CREATE TRIGGER trg_mcp_registry_credentials_bu BEFORE UPDATE ON mcp_registry_credentials FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP credential version is immutable';
CREATE TRIGGER trg_mcp_registry_credentials_bd BEFORE DELETE ON mcp_registry_credentials FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP credential version is immutable';

CREATE TRIGGER trg_mcp_registry_materials_bi BEFORE INSERT ON mcp_registry_materials FOR EACH ROW BEGIN IF (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.materialId'))=BINARY NEW.material_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.registrationId'))=BINARY NEW.registration_id AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.purpose')) IN ('oauth_state','oauth_tokens','as_client') AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.envelope.profile'))='mcp-aes-256-gcm-v1' AND ((JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.purpose'))='as_client' AND NEW.subject_tenant_id IS NULL AND NEW.subject_user_id IS NULL AND JSON_EXTRACT(NEW.record_json,'$.aad.authorizationEpoch')=0) OR (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.purpose'))<>'as_client' AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.subject.tenantId'))=BINARY NEW.subject_tenant_id AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.subject.userId'))=BINARY NEW.subject_user_id)) AND EXISTS (SELECT 1 FROM mcp_registry_versions v WHERE v.config_version_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.configVersionId')) AND BINARY v.config_version_id=BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.configVersionId')) AND v.registration_id=NEW.registration_id AND BINARY v.registration_id=BINARY NEW.registration_id AND JSON_EXTRACT(v.record_json,'$.owner')=JSON_EXTRACT(NEW.record_json,'$.aad.owner') AND JSON_EXTRACT(v.record_json,'$.generation')=JSON_EXTRACT(NEW.record_json,'$.aad.registrationGeneration') AND ((JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.purpose'))='as_client' AND BINARY NEW.material_id=BINARY v.config_version_id AND JSON_EXTRACT(NEW.record_json,'$.aad.registrationRevision')=JSON_EXTRACT(v.record_json,'$.revision')) OR (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.purpose'))='oauth_state' AND EXISTS (SELECT 1 FROM mcp_registry_pending p WHERE p.authorization_id=NEW.material_id AND BINARY p.authorization_id=BINARY NEW.material_id AND p.registration_id=NEW.registration_id AND BINARY p.registration_id=BINARY NEW.registration_id AND p.subject_tenant_id=NEW.subject_tenant_id AND BINARY p.subject_tenant_id=BINARY NEW.subject_tenant_id AND p.subject_user_id=NEW.subject_user_id AND BINARY p.subject_user_id=BINARY NEW.subject_user_id AND JSON_EXTRACT(p.record_json,'$.authorizationEpoch')=JSON_EXTRACT(NEW.record_json,'$.aad.authorizationEpoch') AND JSON_EXTRACT(p.record_json,'$.registrationRevision')=JSON_EXTRACT(NEW.record_json,'$.aad.registrationRevision') AND BINARY JSON_UNQUOTE(JSON_EXTRACT(p.record_json,'$.configVersionId'))=BINARY v.config_version_id)) OR (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.aad.purpose'))='oauth_tokens' AND EXISTS (SELECT 1 FROM mcp_registry_credentials t WHERE t.credential_version_id=NEW.material_id AND BINARY t.credential_version_id=BINARY NEW.material_id AND t.registration_id=NEW.registration_id AND BINARY t.registration_id=BINARY NEW.registration_id AND t.subject_tenant_id=NEW.subject_tenant_id AND BINARY t.subject_tenant_id=BINARY NEW.subject_tenant_id AND t.subject_user_id=NEW.subject_user_id AND BINARY t.subject_user_id=BINARY NEW.subject_user_id AND JSON_EXTRACT(t.record_json,'$.authorizationEpoch')=JSON_EXTRACT(NEW.record_json,'$.aad.authorizationEpoch') AND JSON_EXTRACT(t.record_json,'$.registrationRevision')=JSON_EXTRACT(NEW.record_json,'$.aad.registrationRevision') AND BINARY JSON_UNQUOTE(JSON_EXTRACT(t.record_json,'$.configVersionId'))=BINARY v.config_version_id))))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP material purpose is invalid'; END IF; END;
CREATE TRIGGER trg_mcp_registry_materials_bu BEFORE UPDATE ON mcp_registry_materials FOR EACH ROW BEGIN IF (BINARY NEW.material_id=BINARY OLD.material_id AND BINARY NEW.registration_id=BINARY OLD.registration_id AND (NEW.subject_tenant_id<=>OLD.subject_tenant_id) AND (NEW.subject_user_id<=>OLD.subject_user_id) AND JSON_REMOVE(NEW.record_json,'$.envelope')=JSON_REMOVE(OLD.record_json,'$.envelope') AND JSON_EXTRACT(NEW.record_json,'$.envelope')=CAST('null' AS JSON)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP material only clears'; END IF; END;
CREATE TRIGGER trg_mcp_registry_materials_bd BEFORE DELETE ON mcp_registry_materials FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP material identity is permanent';

CREATE TRIGGER trg_mcp_registry_replays_bi BEFORE INSERT ON mcp_registry_replays FOR EACH ROW BEGIN
  IF (BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.keySha256'))=BINARY NEW.key_sha256
    AND JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.requestSha256')) REGEXP '^[a-f0-9]{64}$'
    AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.registrationId'))=BINARY NEW.registration_id
    AND ((JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.kind'))='registration'
      AND NEW.subject_tenant_id IS NULL AND NEW.subject_user_id IS NULL
      AND EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id
        AND BINARY c.registration_id=BINARY NEW.registration_id AND c.record_json=JSON_EXTRACT(NEW.record_json,'$.result')))
    OR (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.kind'))='begin'
      AND NEW.subject_tenant_id IS NOT NULL AND NEW.subject_user_id IS NOT NULL
      AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.subject.tenantId'))=BINARY NEW.subject_tenant_id
      AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.subject.userId'))=BINARY NEW.subject_user_id
      AND EXISTS (SELECT 1 FROM mcp_registry_pending p WHERE p.authorization_id=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.authorizationId'))
        AND p.registration_id=NEW.registration_id AND BINARY p.registration_id=BINARY NEW.registration_id
        AND p.subject_tenant_id=NEW.subject_tenant_id AND BINARY p.subject_tenant_id=BINARY NEW.subject_tenant_id
        AND p.subject_user_id=NEW.subject_user_id AND BINARY p.subject_user_id=BINARY NEW.subject_user_id
        AND p.record_json=JSON_EXTRACT(NEW.record_json,'$.result')))
    OR (JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.kind'))='authorization'
      AND NEW.subject_tenant_id IS NOT NULL AND NEW.subject_user_id IS NOT NULL
      AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.subject.tenantId'))=BINARY NEW.subject_tenant_id
      AND BINARY JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.subject.userId'))=BINARY NEW.subject_user_id
      AND EXISTS (SELECT 1 FROM mcp_registry_authorizations a WHERE a.authorization_key=JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.result.authorizationKey'))
        AND a.registration_id=NEW.registration_id AND BINARY a.registration_id=BINARY NEW.registration_id
        AND a.subject_tenant_id=NEW.subject_tenant_id AND BINARY a.subject_tenant_id=BINARY NEW.subject_tenant_id
        AND a.subject_user_id=NEW.subject_user_id AND BINARY a.subject_user_id=BINARY NEW.subject_user_id
        AND a.record_json=JSON_EXTRACT(NEW.record_json,'$.result'))))) IS NOT TRUE
  THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP replay identity is invalid'; END IF; END;
CREATE TRIGGER trg_mcp_registry_replays_bu BEFORE UPDATE ON mcp_registry_replays FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP replay is immutable';
CREATE TRIGGER trg_mcp_registry_replays_bd BEFORE DELETE ON mcp_registry_replays FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP replay is immutable';

-- Shared platform configuration alone does not belong to every tenant. Actual user
CREATE TRIGGER trg_mcp_registry_controls_gate_bu BEFORE UPDATE ON mcp_registry_controls FOR EACH ROW BEGIN IF JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state'))='enabled' AND ((NEW.owner_tenant_id IS NULL OR (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.owner_tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.owner_tenant_id AND BINARY t.tenant_id=BINARY NEW.owner_tenant_id AND BINARY t.subject_id=BINARY NEW.owner_tenant_id AND t.state='active' FOR SHARE) AND (NEW.owner_user_id IS NULL OR EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.owner_tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.owner_user_id AND BINARY u.tenant_id=BINARY NEW.owner_tenant_id AND BINARY u.subject_id=BINARY NEW.owner_user_id AND u.state='active' FOR SHARE)) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.owner_tenant_id AND BINARY a.tenant_id=BINARY NEW.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.owner_tenant_id AND BINARY f.tenant_id=BINARY NEW.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.owner_tenant_id AND BINARY r.tenant_id=BINARY NEW.owner_tenant_id FOR SHARE)))) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP owner is not active'; END IF; END;
CREATE TRIGGER trg_mcp_registry_versions_gate_bi BEFORE INSERT ON mcp_registry_versions FOR EACH ROW BEGIN IF NOT EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.registration_id=NEW.registration_id AND BINARY c.registration_id=BINARY NEW.registration_id AND (c.owner_tenant_id IS NULL OR (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=c.owner_tenant_id AND t.subject_kind='tenant' AND t.subject_id=c.owner_tenant_id AND BINARY t.tenant_id=BINARY c.owner_tenant_id AND BINARY t.subject_id=BINARY c.owner_tenant_id AND t.state='active' FOR SHARE) AND (c.owner_user_id IS NULL OR EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=c.owner_tenant_id AND u.subject_kind='user' AND u.subject_id=c.owner_user_id AND BINARY u.tenant_id=BINARY c.owner_tenant_id AND BINARY u.subject_id=BINARY c.owner_user_id AND u.state='active' FOR SHARE)) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=c.owner_tenant_id AND BINARY a.tenant_id=BINARY c.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=c.owner_tenant_id AND BINARY f.tenant_id=BINARY c.owner_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=c.owner_tenant_id AND BINARY r.tenant_id=BINARY c.owner_tenant_id FOR SHARE)))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP owner is not active'; END IF; END;
CREATE TRIGGER trg_mcp_registry_operations_gate_bi BEFORE INSERT ON mcp_registry_operations FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.subject_tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.subject_tenant_id AND BINARY t.tenant_id=BINARY NEW.subject_tenant_id AND BINARY t.subject_id=BINARY NEW.subject_tenant_id AND t.state='active' FOR SHARE) AND EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.subject_tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.subject_tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.subject_tenant_id AND BINARY a.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.subject_tenant_id AND BINARY f.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.subject_tenant_id AND BINARY r.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP credential subject is not active'; END IF; END;
CREATE TRIGGER trg_mcp_registry_credentials_gate_bi BEFORE INSERT ON mcp_registry_credentials FOR EACH ROW BEGIN IF (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.subject_tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.subject_tenant_id AND BINARY t.tenant_id=BINARY NEW.subject_tenant_id AND BINARY t.subject_id=BINARY NEW.subject_tenant_id AND t.state='active' FOR SHARE) AND EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.subject_tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.subject_tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.subject_tenant_id AND BINARY a.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.subject_tenant_id AND BINARY f.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.subject_tenant_id AND BINARY r.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP credential subject is not active'; END IF; END;
CREATE TRIGGER trg_mcp_registry_authorizations_gate_bu BEFORE UPDATE ON mcp_registry_authorizations FOR EACH ROW BEGIN IF JSON_UNQUOTE(JSON_EXTRACT(NEW.record_json,'$.state')) IN ('pending','connected') AND (EXISTS (SELECT 1 FROM subject_lifecycle t WHERE t.tenant_id=NEW.subject_tenant_id AND t.subject_kind='tenant' AND t.subject_id=NEW.subject_tenant_id AND BINARY t.tenant_id=BINARY NEW.subject_tenant_id AND BINARY t.subject_id=BINARY NEW.subject_tenant_id AND t.state='active' FOR SHARE) AND EXISTS (SELECT 1 FROM subject_lifecycle u WHERE u.tenant_id=NEW.subject_tenant_id AND u.subject_kind='user' AND u.subject_id=NEW.subject_user_id AND BINARY u.tenant_id=BINARY NEW.subject_tenant_id AND BINARY u.subject_id=BINARY NEW.subject_user_id AND u.state='active' FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_erasure_admissions a WHERE a.tenant_id=NEW.subject_tenant_id AND BINARY a.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_credential_revocation_fences f WHERE f.tenant_id=NEW.subject_tenant_id AND BINARY f.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE) AND NOT EXISTS (SELECT 1 FROM tenant_restore_fences r WHERE r.tenant_id=NEW.subject_tenant_id AND BINARY r.tenant_id=BINARY NEW.subject_tenant_id FOR SHARE)) IS NOT TRUE THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP credential subject is not active'; END IF; END;

-- Shared platform configuration alone does not belong to every tenant. Actual user
-- authorizations are a separate indexed path even when their registration is platform-owned.
CREATE TRIGGER trg_mcp_registry_t3a_bu BEFORE UPDATE ON tenant_credential_revocation_jobs FOR EACH ROW BEGIN IF OLD.phase<>'credential_store_revoked' AND NEW.phase='credential_store_revoked' AND (EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.owner_tenant_id=NEW.tenant_id AND BINARY c.owner_tenant_id=BINARY NEW.tenant_id FOR SHARE) OR EXISTS (SELECT 1 FROM mcp_registry_authorizations a WHERE a.subject_tenant_id=NEW.tenant_id AND BINARY a.subject_tenant_id=BINARY NEW.tenant_id FOR SHARE)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP registry lifecycle is not proven'; END IF; END;
CREATE TRIGGER trg_mcp_registry_t3d_bu BEFORE UPDATE ON tenant_purge_plan_jobs FOR EACH ROW BEGIN IF OLD.phase<>'plan_sealed' AND NEW.phase='plan_sealed' AND (EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.owner_tenant_id=NEW.tenant_id AND BINARY c.owner_tenant_id=BINARY NEW.tenant_id FOR SHARE) OR EXISTS (SELECT 1 FROM mcp_registry_authorizations a WHERE a.subject_tenant_id=NEW.tenant_id AND BINARY a.subject_tenant_id=BINARY NEW.tenant_id FOR SHARE)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP registry lifecycle is not proven'; END IF; END;
CREATE TRIGGER trg_mcp_registry_t3f_bu BEFORE UPDATE ON tenant_database_purge_jobs FOR EACH ROW BEGIN IF OLD.phase<>'database_purged' AND NEW.phase='database_purged' AND (EXISTS (SELECT 1 FROM mcp_registry_controls c WHERE c.owner_tenant_id=NEW.tenant_id AND BINARY c.owner_tenant_id=BINARY NEW.tenant_id FOR SHARE) OR EXISTS (SELECT 1 FROM mcp_registry_authorizations a WHERE a.subject_tenant_id=NEW.tenant_id AND BINARY a.subject_tenant_id=BINARY NEW.tenant_id FOR SHARE)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='MCP registry lifecycle is not proven'; END IF; END;

-- One calibration root binds all new physical schema metadata and the complete
-- existing+new trigger set/body. No separate root can be chosen as a fallback.
-- agent-service-runtime-fingerprint:mcp-registry:start
SET @skill_registry_triggers_ok=(
  (SELECT COUNT(*)=8 FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%')
  AND (SELECT COUNT(*)=0 FROM information_schema.partitions WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%' AND partition_name IS NOT NULL)
  AND (SELECT COUNT(*)=795 AND SUM(trigger_name LIKE 'trg_mcp_registry_%')=32 AND SUM(OCTET_LENGTH(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4','')))))+COUNT(*)-1<=@@SESSION.group_concat_max_len FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  AND SHA2(CONCAT_WS('::',
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,engine,table_collation,row_format,create_options) ORDER BY table_name SEPARATOR '|'),256) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,LPAD(ordinal_position,3,'0'),column_name,column_type,is_nullable,IFNULL(column_default,'<NULL>'),extra,IFNULL(character_set_name,'-'),IFNULL(collation_name,'-'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(IFNULL(generation_expression,''),'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY table_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,index_name,LPAD(seq_in_index,3,'0'),column_name,non_unique,index_type,IFNULL(collation,'-'),IFNULL(sub_part,'-'),IFNULL(nullable,'-')) ORDER BY table_name,index_name,seq_in_index SEPARATOR '|'),256) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,constraint_type,IFNULL(enforced,'-')) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.table_constraints WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',constraint_name,LOWER(REPLACE(REPLACE(REGEXP_REPLACE(check_clause,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY constraint_name SEPARATOR '|'),256) FROM information_schema.check_constraints WHERE constraint_schema=DATABASE() AND constraint_name='chk_mcp_owner'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,referenced_table_name,update_rule,delete_rule) ORDER BY table_name,constraint_name SEPARATOR '|'),256) FROM information_schema.referential_constraints WHERE constraint_schema=DATABASE() AND table_name LIKE 'mcp_registry_%'),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',table_name,constraint_name,LPAD(ordinal_position,3,'0'),column_name,referenced_table_name,referenced_column_name) ORDER BY table_name,constraint_name,ordinal_position SEPARATOR '|'),256) FROM information_schema.key_column_usage WHERE table_schema=DATABASE() AND table_name LIKE 'mcp_registry_%' AND referenced_table_name IS NOT NULL),
    (SELECT SHA2(GROUP_CONCAT(CONCAT_WS('~',event_object_table,trigger_name,action_timing,event_manipulation,action_orientation,IFNULL(action_condition,'<NULL>'),LOWER(REPLACE(REPLACE(REGEXP_REPLACE(action_statement,'[[:space:]]',''),CHAR(96),''),'_utf8mb4',''))) ORDER BY event_object_table,trigger_name SEPARATOR '|'),256) FROM information_schema.triggers WHERE trigger_schema=DATABASE())
  ),256)='ffb2fae1db46f5b26b43579623d0dc29b6afd64b060ed53ae82ca2fc04b12a01'
);
-- agent-service-runtime-fingerprint:mcp-registry:end
SET @migration_sql=IF(@skill_registry_triggers_ok=1,'SELECT 1','SELECT 1 FROM __invalid_mcp_registry_fingerprint__');
PREPARE migration_stmt FROM @migration_sql;
EXECUTE migration_stmt;
DEALLOCATE PREPARE migration_stmt;
SET SESSION group_concat_max_len=@mcp_previous_gcml;
